package io.knowledgebrain.learning;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class RoadmapGraphTest {
 RoadmapGraph.NodeEdit n(String key){return new RoadmapGraph.NodeEdit(key,"Step "+key,"");}
 RoadmapGraph.EdgeEdit e(String key,String kind,String a,String b){return new RoadmapGraph.EdgeEdit(key,kind,a,b);}
 @Test void mixedPrecedenceAndPartOfCyclesAreRejectedButRelatedAndOptionalCyclesAreAllowed(){var nodes=List.of(n("new:a"),n("new:b"),n("new:c"));assertThrows(RuntimeException.class,()->RoadmapGraph.validate(new RoadmapGraph.Edit(nodes,List.of(e("new:x","PREREQUISITE_OF","new:a","new:b"),e("new:y","REQUIRED_FOR","new:b","new:c"),e("new:z","RECOMMENDED_BEFORE","new:c","new:a")))));assertThrows(RuntimeException.class,()->RoadmapGraph.validate(new RoadmapGraph.Edit(nodes,List.of(e("new:x","PART_OF","new:a","new:b"),e("new:y","PART_OF","new:b","new:a")))));assertDoesNotThrow(()->RoadmapGraph.validate(new RoadmapGraph.Edit(nodes,List.of(e("new:x","RELATED_TO","new:a","new:b"),e("new:y","OPTIONAL_FOR","new:b","new:a")))));}
 @Test void reversedRelatedDuplicateAndMissingSelfOrDuplicateNodesFail(){var nodes=List.of(n("new:a"),n("new:b"));for(var edges:List.of(List.of(e("new:x","RELATED_TO","new:a","new:b"),e("new:y","RELATED_TO","new:b","new:a")),List.of(e("new:x","PART_OF","new:a","new:a")),List.of(e("new:x","PREREQUISITE_OF","new:a","new:c"))))assertThrows(RuntimeException.class,()->RoadmapGraph.validate(new RoadmapGraph.Edit(nodes,edges)));assertThrows(RuntimeException.class,()->RoadmapGraph.validate(new RoadmapGraph.Edit(List.of(n("new:a"),n("new:a")),List.of())));}
 @Test void boundedInputsRejectInvalidIdsControlUnicodeAndOversizedDescriptions(){var nodes=new ArrayList<RoadmapGraph.NodeEdit>();for(int i=0;i<101;i++)nodes.add(n("new:n"+i));assertThrows(RuntimeException.class,()->RoadmapGraph.validate(new RoadmapGraph.Edit(nodes,List.of())));for(String key:List.of("invalid","new:","00000000-0000-4000-8000-000000000001"))assertThrows(RuntimeException.class,()->RoadmapGraph.validate(new RoadmapGraph.Edit(List.of(n(key)),List.of())));for(String title:List.of("","\u0000","line\ncontrol","a".repeat(201),"\ud800"))assertThrows(RuntimeException.class,()->RoadmapGraph.text(title,"",2048));assertDoesNotThrow(()->RoadmapGraph.text("😀".repeat(200),"lines\n\tcontent",2048));assertThrows(RuntimeException.class,()->RoadmapGraph.text("Title","😀".repeat(513),2048));}
}
